// The raid builder's rules for one game build, read from our own game file extract. The JSON beside this
// file is generated by scripts/build-raid-game-data.ts (see README.md); do not edit it by hand.
import raid from "./raid-1.60.1.70685.json";

export type Scope = "self" | "single" | "party" | "raid" | "area" | "enemy" | "mixed" | "unknown";
export type Kind = "buff" | "debuff";

export interface BuffEntry {
  id: string;
  label: string;
  class: string;
  /** Effects in one family do not stack, so the page counts the family once. */
  family: string;
  scope: Scope;
  /**
   * The tree (1 to 3, client order) whose talent gives the class this effect, "baseline" when no talent node
   * matches, or "unknown" when the matches are in more than one tree.
   */
  tree: "baseline" | "unknown" | 1 | 2 | 3;
  /** How the tree was found: a talent with the effect's spell, a learn or trigger link from a talent spell, or a talent of the same name. */
  treeProof?: "talent spell" | "spell chain" | "talent name";
  /** Aura names and spell ids the addon looks for. */
  names: string[];
  spellIds: number[];
  /** Only when ranks disagree (scope "mixed"). */
  byRank?: { rank: number | null; spellIds: number[]; scope: Scope }[];
}

export interface Family {
  id: string;
  label: string;
  kind: Kind;
}

export interface BuffTable {
  build: string;
  /** What the page shows next to the build. */
  label: string;
  families: Family[];
  entries: BuffEntry[];
  /** Tree names per class, in the client's order. */
  trees: Record<string, string[]>;
  notFound: string[];
}

export const CURRENT_BUILD: string = raid.build;
export const TABLES: Record<string, BuffTable> = { [raid.build]: raid as unknown as BuffTable };
